class Solution { fun findWinners(matches:Array<IntArray>):List<List<Int>>{val losses=java.util.TreeMap<Int,Int>();for(match in matches){losses.putIfAbsent(match[0],0);losses[match[1]]=(losses[match[1]]?:0)+1};val zero=mutableListOf<Int>();val one=mutableListOf<Int>();for((player,count) in losses)if(count==0)zero.add(player)else if(count==1)one.add(player);return listOf(zero,one)} }
